def parse_due(val):
    s = str(val).strip()
    s_clean = s.replace('5pm', ' 5 PM').replace('5PM', ' 5 PM')
    for fmt in ('%Y-%m-%d %H:%M', '%Y-%m-%d', '%m/%d/%Y', '%b %d %Y', '%b %d %Y %I %p', '%b %d %I %p', '%b %d'):
        try:
            if fmt == '%b %d':
                dt = datetime.strptime(s_clean, '%b %d')
                return dt.replace(year=2026, hour=23, minute=59)
            if fmt == '%b %d %I %p':
                dt = datetime.strptime(s_clean, '%b %d %I %p')
                return dt.replace(year=2026)
            dt = datetime.strptime(s_clean, fmt)
            if dt.hour == 0 and dt.minute == 0 and ' ' not in s_clean and ':' not in s_clean:
                dt = dt.replace(hour=23, minute=59)
            return dt
        except ValueError:
            continue
    raise ValueError(f"Cannot parse {val}")

